/* ---------- assistant ---------- */
function reply(q){const t=tod(),bk=books();
if(/وزن|عروض|هجا/.test(q))return 'برای هجا: هجای کوتاه = صامت + مصوت کوتاه (∪)، هجای بلند = مصوت بلند یا ختم به صامت (—). در «مربی وزن شعر» با لمس مربع‌ها تمرین کن.';
if(/تحلیل|عملکرد|وضعیت/.test(q)){const a=S.logs.filter(l=>l.n);if(!a.length)return 'هنوز داده‌ی تستی نداری. چند تمرین ثبت کن تا تحلیل کنم.';const m={};a.forEach(l=>{m[l.b]=m[l.b]||{c:0,w:0,n:0};m[l.b].c+=l.c;m[l.b].w+=l.w;m[l.b].n+=l.n});const r=Object.entries(m).map(([b,x])=>[b,Math.round((x.c*3-x.w)/(x.n*3)*100)]).sort((x,y)=>x[1]-y[1]);return `ضعیف‌ترین: ${r[0][0]} (${fa(r[0][1])}٪) و قوی‌ترین: ${r[r.length-1][0]} (${fa(r[r.length-1][1])}٪). امروز ${fa(sum(t,'min'))} دقیقه خوانده‌ای.`}
if(/برنامه/.test(q))return `پیشنهاد روزانه: ۴۵ دقیقه ${bk[0]}، ۳۰ دقیقه ${bk[1]}، ۳۰ دقیقه تست و ۱۵ دقیقه مرور فلش‌کارت. درس‌های ضعیفت را اول روز بخوان.`;
if(/آرایه/.test(q))return 'آرایه‌های ادبی: تشبیه، استعاره، کنایه، تضاد، جناس و مراعات‌نظیر. برای هر کدام یک مثال بنویس و فلش‌کارت بساز.';
if(/تشبیه/.test(q))return 'تشبیه: مانند کردن چیزی به چیز دیگر. چهار رکن: مشبه، مشبه‌به، ادات و وجه شبه. مثال: «او مثل ماه زیباست».';
if(/استعاره/.test(q))return 'استعاره: تشبیهی که فقط مشبه‌به در آن آمده است. مثل «ماه آمد» برای انسانی زیبا.';
return 'سؤال خوبی است! کمی دقیق‌تر بگو، یا از این‌ها بپرس: تحلیل عملکرد، برنامه، وزن شعر، تشبیه، استعاره، آرایه.'}
