lvl(d){P={lv:+d.v,i:0,ans:[],res:null,meter:null,wn:6,wp:[]};draw()},
pk(d){if(P.res&&P.good)return;P.ans[+d.i]=d.v;P.res=null;draw()},
pm(d){P.meter=d.v;P.res=null;draw()},
