chk(){const it=item();if(it.p.some((p,i)=>P.ans[i]!=p)||false){P.res=1;P.good=false}else{P.res=1;P.good=P.lv!=3||P.meter==it.v.m;if(P.lv==3&&!P.good)toast('هجاها درست است؛ وزن را دوباره بررسی کن')}
if(P.res&&P.ans.length<it.p.length)P.good=false;
if(P.good){S.xp+=10;S.done['l'+P.lv]=(S.done['l'+P.lv]||0)+1;save()}draw()},
nxt(){P.i++;P.ans=[];P.res=null;P.meter=null;P.good=false;draw()},
wn(d){P.wn=Math.max(2,Math.min(12,P.wn+ +d.d));draw()},
