<div class="card"><h3>۱) تقطیع</h3><div class="paper"><div class="mut" style="text-align:center">${v.poet} · از متون درسی</div><div class="verse">${v.t}</div><div class="step"><span>تعداد مربع‌ها</span><span class="row" style="flex:none"><button data-a="qn" data-d="-1">−</button><b>${fa(Q.n)}</b><button data-a="qn" data-d="1">+</button></span></div><div class="cs">${Array.from({length:Q.n},(_,i)=>`<div class="col"><div class="sq ${c?(i<ex.length?(s[i]==ex[i]?'ok':'bad'):(s[i]?'bad':'')):''}">${s[i]?SYM(s[i]):''}</div><div class="pb"><button data-a="cp" data-i="${i}" data-v="S" class="${s[i]=='S'?'on':''}" aria-label="کوتاه">∪</button><button data-a="cp" data-i="${i}" data-v="L" class="${s[i]=='L'?'on':''}" aria-label="بلند">—</button></div><div class="lab">${c&&v.s[i]?v.s[i]:''}</div></div>`).join('')}</div></div>
${Q.hint?`<p class="ai" style="margin-top:10px">💡 ${H[Q.hint]}</p>`:''}${c?`<div style="margin-top:10px">${c.m.map(x=>`<p class="${c.ok?'ok-t':'ex'}">${x}</p>`).join('')}</div>`:''}
<div class="row" style="margin-top:10px"><button class="btn s" data-a="qh">💡 راهنمایی ${fa(Q.hint)}/۳</button><button class="btn" data-a="qc">بررسی تقطیع</button></div></div>
