async mc(){const t=M.t.trim();if(!t)return toast('شعرت را بنویس');const sm=await useSample();if(!sm)return toast('این بخش فقط در نسخه منتشرشده کار می‌کند');M.busy=1;M.err='';M.o=null;M.pat='';M.rs=null;draw();let out='';try{await sm(SYS+' این شعر را تحلیل کن: «'+t+'». فقط یک شیء JSON برگردان و هیچ متن دیگری ننویس، با این کلیدها: syl (آرایه‌ی هجاهای مصراع اول)، pat (رشته‌ای از S برای کوتاه و L برای بلند، هم‌طول با syl)، feet (آرایه‌ی نام ارکان مصراع اول)، meter (نام کامل وزن)، rhyme (کلمات قافیه)، radif (ردیف یا ندارد)، notes (آرایه‌ی توضیح مرحله‌به‌مرحله به فارسی ساده و دوستانه)، issues (آرایه‌ی ایرادهای وزنی یا قافیه‌ای؛ خالی اگر ایرادی نبود). اگر مطمئن نیستی در notes بگو.',{cache:false,onText:({text})=>{out=text}})}catch(e){M.err=errT(e)}try{const o=JSON.parse(out.slice(out.indexOf('{'),out.lastIndexOf('}')+1)),pat=String(o.pat||'').replace(/[^SL]/g,'');if(!pat||!Array.isArray(o.syl)||o.syl.length!=pat.length)throw 0;M.o=o;M.pat=pat;M.warn=dec(pat)?'':'این الگو با ارکان رایج نمی‌خواند؛ احتمال خطای تحلیل هست.'}catch(e){if(!M.err)M.err='نتوانستم شعر را تحلیل کنم؛ دوباره امتحان کن یا شعر را ساده‌تر بنویس.'}M.busy=0;draw()},
